-- lovable-cron-fallback-reviewed: Bounded interview queue wakes on enqueue and removes five-minute retry scheduling after drain; no idle sweeper.
CREATE TABLE public.interview_sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, job_id uuid, title text NOT NULL DEFAULT 'Interview preparation', employer text, jd text NOT NULL, resume_text text, settings jsonb NOT NULL DEFAULT '{}', cache_key text NOT NULL, status text NOT NULL DEFAULT 'queued' CHECK(status IN ('queued','processing','completed','failed','paused','cancelled')), analysis jsonb, error text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL DEFAULT now()+interval '30 days', lease_until timestamptz, retry_at timestamptz, attempts integer NOT NULL DEFAULT 0, current_question integer NOT NULL DEFAULT 0);
GRANT SELECT, DELETE ON public.interview_sessions TO authenticated; GRANT ALL ON public.interview_sessions TO service_role;
ALTER TABLE public.interview_sessions ENABLE ROW LEVEL SECURITY;
CREATE POLICY interview_session_owner ON public.interview_sessions FOR SELECT TO authenticated USING(user_id=auth.uid() AND expires_at>now());
CREATE POLICY interview_session_delete ON public.interview_sessions FOR DELETE TO authenticated USING(user_id=auth.uid());
CREATE INDEX interview_session_queue ON public.interview_sessions(status,retry_at,created_at);
CREATE INDEX interview_session_owner_cache ON public.interview_sessions(user_id,cache_key);
CREATE TABLE public.interview_questions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), session_id uuid NOT NULL REFERENCES public.interview_sessions(id) ON DELETE CASCADE, position integer NOT NULL, category text NOT NULL, question text NOT NULL, UNIQUE(session_id,position));
GRANT SELECT ON public.interview_questions TO authenticated; GRANT ALL ON public.interview_questions TO service_role;
ALTER TABLE public.interview_questions ENABLE ROW LEVEL SECURITY;
CREATE POLICY interview_question_owner ON public.interview_questions FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.interview_sessions s WHERE s.id=session_id AND s.user_id=auth.uid() AND s.expires_at>now()));
CREATE TABLE public.interview_answers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), question_id uuid NOT NULL UNIQUE REFERENCES public.interview_questions(id) ON DELETE CASCADE, session_id uuid NOT NULL REFERENCES public.interview_sessions(id) ON DELETE CASCADE, content jsonb NOT NULL);
GRANT SELECT ON public.interview_answers TO authenticated; GRANT ALL ON public.interview_answers TO service_role;
ALTER TABLE public.interview_answers ENABLE ROW LEVEL SECURITY;
CREATE POLICY interview_answer_owner ON public.interview_answers FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.interview_sessions s WHERE s.id=session_id AND s.user_id=auth.uid() AND s.expires_at>now()));
CREATE TABLE public.interview_feedback (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), session_id uuid NOT NULL REFERENCES public.interview_sessions(id) ON DELETE CASCADE, question_id uuid NOT NULL REFERENCES public.interview_questions(id) ON DELETE CASCADE, candidate_answer text NOT NULL, content jsonb, status text NOT NULL DEFAULT 'queued', error text, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.interview_feedback TO authenticated; GRANT ALL ON public.interview_feedback TO service_role;
ALTER TABLE public.interview_feedback ENABLE ROW LEVEL SECURITY;
CREATE POLICY interview_feedback_owner ON public.interview_feedback FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.interview_sessions s WHERE s.id=session_id AND s.user_id=auth.uid() AND s.expires_at>now()));
CREATE TABLE public.interview_preparation_plans (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), session_id uuid NOT NULL UNIQUE REFERENCES public.interview_sessions(id) ON DELETE CASCADE, content jsonb NOT NULL);
GRANT SELECT ON public.interview_preparation_plans TO authenticated; GRANT ALL ON public.interview_preparation_plans TO service_role;
ALTER TABLE public.interview_preparation_plans ENABLE ROW LEVEL SECURITY;
CREATE POLICY interview_plan_owner ON public.interview_preparation_plans FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.interview_sessions s WHERE s.id=session_id AND s.user_id=auth.uid() AND s.expires_at>now()));
CREATE TABLE public.resume_analysis (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), session_id uuid NOT NULL UNIQUE REFERENCES public.interview_sessions(id) ON DELETE CASCADE, content jsonb NOT NULL);
GRANT SELECT ON public.resume_analysis TO authenticated; GRANT ALL ON public.resume_analysis TO service_role;
ALTER TABLE public.resume_analysis ENABLE ROW LEVEL SECURITY;
CREATE POLICY resume_analysis_owner ON public.resume_analysis FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.interview_sessions s WHERE s.id=session_id AND s.user_id=auth.uid() AND s.expires_at>now()));
CREATE TABLE public.ai_usage_metrics (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, session_id uuid REFERENCES public.interview_sessions(id) ON DELETE SET NULL, operation text NOT NULL, input_tokens integer NOT NULL DEFAULT 0, output_tokens integer NOT NULL DEFAULT 0, status text NOT NULL DEFAULT 'reserved', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.ai_usage_metrics TO authenticated; GRANT ALL ON public.ai_usage_metrics TO service_role;
ALTER TABLE public.ai_usage_metrics ENABLE ROW LEVEL SECURITY;
CREATE POLICY ai_usage_owner ON public.ai_usage_metrics FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE INDEX ai_usage_user_day ON public.ai_usage_metrics(user_id,created_at);
CREATE TABLE public.interview_engine_state (id text PRIMARY KEY DEFAULT 'interview', paused boolean NOT NULL DEFAULT false, reason text, lease_until timestamptz, updated_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.interview_engine_state TO service_role; ALTER TABLE public.interview_engine_state ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public.reserve_interview_usage(p_user uuid,p_session uuid,p_operation text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE result uuid; BEGIN PERFORM pg_advisory_xact_lock(hashtext(p_user::text)); IF (SELECT count(*) FROM public.ai_usage_metrics WHERE user_id=p_user AND created_at>date_trunc('day',now()))>=60 THEN RAISE EXCEPTION 'Daily AI request limit reached; try tomorrow'; END IF; INSERT INTO public.ai_usage_metrics(user_id,session_id,operation) VALUES(p_user,p_session,p_operation) RETURNING id INTO result; RETURN result; END $$;
REVOKE ALL ON FUNCTION public.reserve_interview_usage(uuid,uuid,text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.reserve_interview_usage(uuid,uuid,text) TO service_role;
CREATE OR REPLACE FUNCTION public.claim_interview_work() RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE result uuid; BEGIN INSERT INTO public.interview_engine_state(id) VALUES('interview') ON CONFLICT DO NOTHING; UPDATE public.interview_engine_state SET lease_until=now()+interval '10 minutes' WHERE id='interview' AND NOT paused AND (lease_until IS NULL OR lease_until<now()); IF NOT FOUND THEN RETURN NULL; END IF; SELECT id INTO result FROM public.interview_sessions WHERE expires_at>now() AND ((status='queued' AND (retry_at IS NULL OR retry_at<=now())) OR (status='processing' AND lease_until<now())) ORDER BY created_at LIMIT 1 FOR UPDATE SKIP LOCKED; IF result IS NULL THEN UPDATE public.interview_engine_state SET lease_until=NULL WHERE id='interview'; RETURN NULL; END IF; UPDATE public.interview_sessions SET status='processing',lease_until=now()+interval '10 minutes',updated_at=now() WHERE id=result; RETURN result; END $$;
REVOKE ALL ON FUNCTION public.claim_interview_work() FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.claim_interview_work() TO service_role;
CREATE OR REPLACE FUNCTION public.commit_interview_batch(p_session uuid,p_analysis jsonb,p_questions jsonb,p_plan jsonb,p_resume jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE q jsonb; qid uuid; n integer; target integer; BEGIN PERFORM 1 FROM public.interview_sessions WHERE id=p_session AND status='processing' FOR UPDATE; IF NOT FOUND THEN RETURN; END IF; SELECT count(*) INTO n FROM public.interview_questions WHERE session_id=p_session; FOR q IN SELECT value FROM jsonb_array_elements(p_questions) LOOP INSERT INTO public.interview_questions(session_id,position,category,question) VALUES(p_session,n,q->>'category',q->>'question') RETURNING id INTO qid; INSERT INTO public.interview_answers(question_id,session_id,content) VALUES(qid,p_session,q); n:=n+1; END LOOP; IF p_plan IS NOT NULL THEN INSERT INTO public.interview_preparation_plans(session_id,content) VALUES(p_session,p_plan) ON CONFLICT(session_id) DO UPDATE SET content=excluded.content; END IF; IF p_resume IS NOT NULL THEN INSERT INTO public.resume_analysis(session_id,content) VALUES(p_session,p_resume) ON CONFLICT(session_id) DO UPDATE SET content=excluded.content; END IF; SELECT (settings->>'count')::integer INTO target FROM public.interview_sessions WHERE id=p_session; UPDATE public.interview_sessions SET analysis=coalesce(analysis,p_analysis),status=CASE WHEN n>=target THEN 'completed' ELSE 'queued' END,lease_until=NULL,retry_at=now()+interval '20 seconds',updated_at=now(),attempts=0 WHERE id=p_session; UPDATE public.interview_engine_state SET lease_until=NULL WHERE id='interview'; END $$;
REVOKE ALL ON FUNCTION public.commit_interview_batch(uuid,jsonb,jsonb,jsonb,jsonb) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.commit_interview_batch(uuid,jsonb,jsonb,jsonb,jsonb) TO service_role;
CREATE OR REPLACE FUNCTION public.wake_interview_queue() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE cmd text; BEGIN IF NEW.status='queued' AND NEW.expires_at>now() THEN SELECT replace(command,'/api/public/cron/jobs-sync','/api/public/cron/interview-worker') INTO cmd FROM cron.job WHERE jobname='jobs-sync-15min' LIMIT 1; IF cmd IS NOT NULL AND NOT EXISTS(SELECT 1 FROM cron.job WHERE jobname='interview-queue-retry') THEN PERFORM cron.schedule('interview-queue-retry','*/5 * * * *',cmd); END IF; IF cmd IS NOT NULL AND TG_OP='INSERT' THEN EXECUTE cmd; END IF; END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.wake_interview_queue() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER interview_wake_on_enqueue AFTER INSERT OR UPDATE OF status ON public.interview_sessions FOR EACH ROW EXECUTE FUNCTION public.wake_interview_queue();
CREATE OR REPLACE FUNCTION public.drain_interview_queue() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.interview_sessions WHERE status IN ('queued','processing') AND expires_at>now()) THEN PERFORM cron.unschedule(jobid) FROM cron.job WHERE jobname='interview-queue-retry'; END IF; END $$;
REVOKE ALL ON FUNCTION public.drain_interview_queue() FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.drain_interview_queue() TO service_role;